const MEAL_REPLACED_NAMES = { 'meal-beef-and-black-bean': 'Beef and black bean', 'meal-sausage-sizzle': 'Sausage sizzle' };
const STARTER_VER = 4; // 2.26.24: 17 veg-packed gluten-free recipes added
