        [[addDays(x.date, -3), '🔔 ' + x.title + ' is due in 3 days', 'b'], [x.date, '🔔 ' + x.title + ' is due today', 'd'], [addDays(x.date, 1), '⚠️ ' + x.title + ' was due yesterday', 'o']]
