  const mins = Math.round((next.ms - now) / 60000);
  const inTxt = mins < 60 ? `in ${Math.max(1, mins)} min` : `in ${Math.floor(mins / 60)} h${mins % 60 ? ' ' + (mins % 60) + ' min' : ''}`;
  const after = list.find(x => x.ms > next.ms);
