  acc.seen[ch[1]] = true;
  const start = tvStamp((/\bstart="([^"]+)"/.exec(attrs) || [])[1]);
  const until = tvStamp((/\bstop="([^"]+)"/.exec(attrs) || [])[1]);
  if (start == null || until == null || until <= now || start >= now + TV_AHEAD) return;
