    return { key: k, title, dow: g[0].w, time: String(Math.floor(med / 60)).padStart(2, '0') + ':' + String(med % 60).padStart(2, '0'), notes: '', why: `You’ve been at ${title === 'Gym' ? 'the gym' : title} on ${WD_NAMES[g[0].w]}s around ${hmTxt(med)}` };
