    tbList('coming', 'Coming soon', C.length, co, false, 'pr', 'Nothing listed as coming soon') +
    PR_LISTS.map(([k, t2]) => tbList(k, t2, o.lists[k].length, o.lists[k].map(c => prUserCard(k, c)).join(''), true, 'pr', 'Tap a title or + Add a card')).join('');
