async function homeWeekBillsToggle() { try { S.settings = S.settings || {}; S.settings.homeWeekBills = !S.settings.homeWeekBills; await save(); const v = $('#view'), top = v ? v.scrollTop : 0; render(); if (v) v.scrollTop = top; } catch (e) { } }
