function hwLast(n) { const out = []; for (let i = n - 1; i >= 0; i--) { const d = new Date(Date.now() - i * 864e5), k = nzISO(d.getTime()); out.push({ date: k, x: hwDay(k) }); } return out; }
// small bar chart: [{label, v}] → bars scaled to the biggest
