  const hr = hwLast(14).map(o => ({ label: HW_DOW[new Date(o.date + 'T12:00:00').getDay()], v: o.x && o.x.hr && o.x.hr.rest || 0, today: o.date === T, est: o.x && o.x.hr && o.x.hr.restEst }));
