function irRules(k) { const w = irSt(k); return w.rules.map(r => `<span class="cftag income">${esc(r)} <button type="button" class="linkbtn" aria-label="Remove ${esc(r)}" onclick="irDrop('${k}',${jsArg(r)})">✕</button></span>`).join(' '); }
