    sec('Reminders', rmL.length ? `<div class="list">${rmL.map(x => x.html).join('')}</div>` : '') +
    mbSections(p.mb);
  // 2.26.77: New today sits at the very top (compact rows), above Flagged events, Urgent and Reminders
