  if (late) c.entries.push({ id: uid('comm'), date: r.from, cents: late, note: `Earlier sales settled (${fmt(lateDays[0])}${lateDays.length > 1 ? ' – ' + fmt(lateDays[lateDays.length - 1]) : ''})`.slice(0, 80), src: 'email', slip: r.to });
