  const tm = win.match(/\b(\d{1,2})(?:[:.](\d{2}))\s*(am|pm)\b/i) || win.match(/\bat\s+(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)\b/i) || win.match(/\b(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)\b/i) || win.match(/\b(?:at\s+)?([01]?\d|2[0-3])[:.]([0-5]\d)\b(?!\s*\/)/);
