  const T = total != null ? total : (() => { const m = t.match(/\btotal(?:\s+commission)?(?:\s+payable)?\s*:?\s*\$?\s*(-?[\d,]+\.\d\d-?)/i); return m ? cpNum(m[1]) : null; })();
  if (T != null && Math.abs(T) < 5000000) return { from, to, cents: T, days: { [from]: T }, approx: true };
