function flgChips() { const n = f => f === 'all' ? flgGet().items.length : flgGet().items.filter(x => ((FLG_SRC[(x.src || {}).type] || [0, 'other'])[1]) === f).length;
  return [['list', 'List'], ['board', 'Board']].map(([k, t]) => `<button type="button" class="chip ${flgView === k ? 'on' : ''}" onclick="flgView='${k}';flgRedraw()">${t}</button>`).join('') + '<span style="width:10px"></span>' +
    [['all', 'All'], ['events', 'Events'], ['bills', 'Bills'], ['todos', 'To-dos'], ['other', 'Other']].map(([k, t]) => `<button type="button" class="chip ${flgF === k ? 'on' : ''}" onclick="flgF='${k}';flgRedraw()">${t} ${n(k) ? `<span class="muted">${n(k)}</span>` : ''}</button>`).join(''); }
function flgRedraw() { const el = document.getElementById('flgbody'); if (!el) { if (/^#flagged/.test(location.hash)) render(); return; } el.innerHTML = flgBodyHtml(); const c = document.getElementById('flgchips'); if (c) c.innerHTML = flgChips(); }
async function btAddFlagged() {
  const s = snap(), b = btState();
  if (b.keys.includes('flagged')) { if (!b.on) { b.on = true; await save(); render(); } toast('Flagged is on your bottom tabs.'); return; }
  if (b.keys.length >= BT_MAX) { toast('Six tabs is the most. Remove one, then add Flagged.'); btCustomise(); return; }
  const i = b.keys.indexOf('more'); b.keys.splice(i < 0 ? b.keys.length : i, 0, 'flagged'); b.on = true; await save(); render(); toast('Flagged added to your bottom tabs.', 'Undo', undoTo(s));
}
function FlaggedPage() {
  const btIn = (() => { try { const b = btState(); return b.on && b.keys.includes('flagged'); } catch (e) { return true; } })();
  return header('Flagged', 'Things you’ve flagged to build on') + (btIn ? '' : `<button type="button" class="btn small" style="margin:0 0 10px" onclick="btAddFlagged()">${I('plus')} Add to bottom bar</button>`) +
    `<div class="chips" id="flgchips">${flgChips()}</div><div id="flgbody">${flgBodyHtml()}</div><div class="foot">Saved on this phone and in your backups. If the original goes, your flagged copy stays.</div>`;
}
function flgCuHtml() {
  const T = todayISO(); return flgGet().items.filter(x => x.status !== 'done' && x.due && x.due <= T).map(x => `<button class="row" onclick="flgOpen(${jsArg(x.id)})"><div class="ic">${flgFlag(x.pri)}</div><div class="tx"><div class="t">${esc(x.title)}</div><div class="s"${x.due < T ? ' style="color:var(--red);font-weight:650"' : ''}>Flagged · ${esc(x.due < T ? 'Overdue since ' + fmtW(x.due) : 'Due today')}${flgProg(x).n ? ' · ' + flgProg(x).d + '/' + flgProg(x).n + ' sub-tasks' : ''}</div></div></button>`).join('');
}
function flaggedMoreSub() { const L = flgGet().items.filter(x => x.status !== 'done'); return L.length ? plural(L.length, 'open item') : 'Flag things to build on them'; }

// 2.27.88: show or hide bills on Home
function homeBillsToggle() { try { S.settings = S.settings || {}; S.settings.homeBillsOff = !S.settings.homeBillsOff; save(); const v = $('#view'), top = v ? v.scrollTop : 0; render(); if (v) v.scrollTop = top; } catch (e) { } }

// 2.27.99: hold down a subject list on the Videos board to remove that subject (confirm and Undo come from askRemoveVideoCat)
(() => { let t = null, x0 = 0, y0 = 0, fired = false;
  const clear = () => { if (t) { clearTimeout(t); t = null; } };
  document.addEventListener('pointerdown', e => { const sec = e.target.closest && e.target.closest('#vblists section.tblist[data-k^="c_"]'); fired = false; clear(); if (!sec) return;
    x0 = e.clientX; y0 = e.clientY; const id = sec.dataset.k.slice(2);
    t = setTimeout(() => { t = null; fired = true; try { navigator.vibrate && navigator.vibrate(30); } catch (er) { } askRemoveVideoCat(id); }, 650); }, { passive: true });
  document.addEventListener('pointermove', e => { if (t && (Math.abs(e.clientX - x0) > 10 || Math.abs(e.clientY - y0) > 10)) clear(); }, { passive: true });
  ['pointerup', 'pointercancel', 'scroll'].forEach(n => document.addEventListener(n, clear, { passive: true, capture: true }));
  document.addEventListener('click', e => { if (fired && e.target.closest && e.target.closest('#vblists')) { e.preventDefault(); e.stopPropagation(); fired = false; } }, true);
  document.addEventListener('contextmenu', e => { if (e.target.closest && e.target.closest('#vblists section.tblist[data-k^="c_"]')) e.preventDefault(); });
})();


/* ================= 2.28.18: NORTHLAND WALKS & BEACHES (#walks) =================
   Trello-style board & directory of Whangārei and Northland bushwalks and beaches.
   Drive distance/time from Onerahi (16 Sherwood Rd), walk time & difficulty, Zeus dog badge,
   best tide/weather notes, Wikipedia/Wikimedia Commons photos, filter chips and custom walks. */
const WALKS = [{"id":"onerahi","name":"Onerahi Foreshore & Waimahanga Track","area":"Onerahi","cat":"both","catLabel":"Coastal & Bush","km":2,"driveMin":3,"walkTime":"45–60 min return","diff":"Easy","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Any tide · flat sheltered harbour path & railway embankment","lat":-35.7563,"lon":174.3585,"paras":["Starting right down the hill at the Onerahi foreshore (Beach Road), this flat, easy walk follows the harbour edge before joining the Waimahanga Track along the old Onerahi railway embankment through mangroves and regenerating bush to Raulands Reserve.","Because it is right on your doorstep from Sherwood Road and sheltered from open-coast wind, it is one of the easiest everyday walks with Zeus on-lead at any tide."],"img":"https://upload.wikimedia.org/wikipedia/commons/8/81/Onerahi_Aerial.jpg","credit":"Uploader, Public domain, Wikimedia Commons","file":"Onerahi_Aerial.jpg","wiki":"Onerahi"},{"id":"falls","name":"Whangārei Falls (Otuihau)","area":"Tikipunga","cat":"bush","catLabel":"Bushwalk & Waterfall","km":12,"driveMin":16,"walkTime":"30 min loop","diff":"Easy","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Great year-round · spectacular after rain","lat":-35.6852,"lon":174.3361,"paras":["A classic 26-metre curtain waterfall over basalt cliffs on the Hātea River in Tikipunga. Two upper viewing platforms sit right by the car park and grassy picnic area, while a well-formed bush loop drops down steps to the footbridge across the pool.","Dogs on a lead are welcome on the loop track and picnic lawns. You can also link it with the Hātea River walkway down to A.H. Reed Kauri Park."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0d/Whangarei_Water_Fall.jpg/960px-Whangarei_Water_Fall.jpg","credit":"GingerChicken34, CC BY-SA 4.0, Wikimedia Commons","file":"Whangarei_Water_Fall.jpg","wiki":"Whangārei Falls"},{"id":"ahreed","name":"A.H. Reed Memorial Kauri Park","area":"Whareora Rd","cat":"bush","catLabel":"Bushwalk","km":10,"driveMin":14,"walkTime":"30–45 min loop","diff":"Easy","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Shaded canopy boardwalk · cool on hot days","lat":-35.7022,"lon":174.3425,"paras":["Walk high among 500-year-old kauri trees on the elevated treetop boardwalk in the Alexanderulloch Reserve, then loop past Paranui Falls along the shady stream gully.","Most of the main canopy loop is boardwalk and gentle gravel, making it mud-free in winter and cool in summer. Dogs are allowed on a lead."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/00_29_0496_Waipoua_Forest_NZ_-_Kauri_Baum_Tane_Mahuta.jpg/960px-00_29_0496_Waipoua_Forest_NZ_-_Kauri_Baum_Tane_Mahuta.jpg","credit":"W. Bulach, CC BY-SA 4.0, Wikimedia Commons","file":"00_29_0496_Waipoua_Forest_NZ_-_Kauri_Baum_Tane_Mahuta.jpg","wiki":"Agathis australis"},{"id":"parihaka","name":"Parihaka Lookout & Ross Track","area":"Parihaka / Mair Park","cat":"bush","catLabel":"Bushwalk","km":8,"driveMin":12,"walkTime":"1–1.5 hr return","diff":"Moderate","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Clear morning or late afternoon for harbour views","lat":-35.7161,"lon":174.3358,"paras":["Climb from Mair Park on the Hātea River up through native bush (via the Ross, Dobbie, or Drummond tracks) to the 241-metre summit of Parihaka, an ancient volcanic cone and the site of one of New Zealand’s largest pre-European pā.","From the war memorial lookout at the top you get sweeping views right down Whangārei Harbour to Onerahi and Marsden Point. Dogs on-lead are welcome."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Parihaka_te_Maunga.jpg/960px-Parihaka_te_Maunga.jpg","credit":"Wikimedia Commons","file":"Parihaka_te_Maunga.jpg","wiki":"Whangārei"},{"id":"abbey","name":"Abbey Caves Reserve (Karst Loop)","area":"Abbey Caves Rd","cat":"bush","catLabel":"Bushwalk","km":8,"driveMin":11,"walkTime":"45 min loop","diff":"Moderate","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Dry weather · fascinating fluted limestone outcrops","lat":-35.7138,"lon":174.3672,"paras":["Just 11 minutes from Onerahi via Whareora Road, the above-ground walking track winds across dramatic fluted Tikorangi limestone outcrops, sinkholes, and regenerating bush.","Even without going underground into the caves, the surface loop is a great short local walk with unique geology and rural views."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Zadar_%28HR%29%2C_Krupa-Canyon_--_2022_--_0003.jpg/960px-Zadar_%28HR%29%2C_Krupa-Canyon_--_2022_--_0003.jpg","credit":"Wikimedia Commons","file":"3840px-Zadar_(HR),_Krupa-Canyon_--_2022_--_0003.jpg","wiki":"Karst"},{"id":"hatea","name":"Hātea River Walk (Mair Park to Falls)","area":"Town Basin / Mair Park","cat":"bush","catLabel":"Bushwalk","km":7,"driveMin":10,"walkTime":"1.5–2 hr return","diff":"Easy","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Calm riverside bush · pick a short or long section","lat":-35.7185,"lon":174.3292,"paras":["Follows the bubbling Hātea River through native totara, nikau, and kauri from Mair Park through A.H. Reed Kauri Park all the way to Whangārei Falls.","You can do a gentle 40-minute out-and-back from Mair Park with Zeus on-lead or tackle the full riverside corridor on a day off."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/H%C4%81tea_River.jpg/960px-H%C4%81tea_River.jpg","credit":"Ulrich Lange, Bochum, Germany, CC BY 3.0, Wikimedia Commons","file":"Hātea_River.jpg","wiki":"Hātea River"},{"id":"coronation","name":"Coronation Reserve & Western Hills","area":"Central Whangārei","cat":"bush","catLabel":"Bushwalk","km":8,"driveMin":12,"walkTime":"1–1.5 hr loop","diff":"Moderate","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Sheltered bush tracks on breezy days","lat":-35.729,"lon":174.311,"paras":["Tucked behind Rust Avenue and Manse Street, Coronation Scenic Reserve offers quiet native forest tracks through mature puriri, rimu, and kauri along the Western Hills ridge.","Close to town and Port Road, it is a peaceful bush escape when you want a proper hill stretch without a long drive."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Whangarei_Harbour.JPG/960px-Whangarei_Harbour.JPG","credit":"Follash, Public domain, Wikimedia Commons","file":"Whangarei_Harbour.JPG","wiki":"Whangārei Harbour"},{"id":"ruakaka","name":"Ruakākā Beach & Estuary","area":"Ruakākā / Bream Bay","cat":"beach","catLabel":"Beaches","km":34,"driveMin":32,"walkTime":"45–90 min beach walk","diff":"Easy","dog":"offlead","dogBadge":"🐕 Zeus off-lead areas","best":"Low to mid tide · wide hard sand for a long beach walk","lat":-35.9082,"lon":174.4596,"paras":["Stretching along the sweep of Bream Bay with views back to Mount Manaia and Bream Head, Ruakākā offers kilometres of firm golden sand and rolling surf.","Outside the protected wildlife refuge at the estuary mouth, designated stretches of the open beach allow off-lead dog exercise—making it a top spot for Zeus to stretch his legs."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Bream_Bay_panorama.jpg/960px-Bream_Bay_panorama.jpg","credit":"Glenn h, CC BY-SA 3.0, Wikimedia Commons","file":"Bream_Bay_panorama.jpg","wiki":"Bream Bay"},{"id":"manaia","name":"Mount Manaia Track","area":"Whangārei Heads","cat":"bush","catLabel":"Bushwalk","km":25,"driveMin":28,"walkTime":"1.5–2 hr return","diff":"Steep/Steps","dog":"no","dogBadge":"🚫 No dogs (DOC reserve)","best":"Clear calm day · unbeatable 360° harbour & island views","lat":-35.8175,"lon":174.5169,"paras":["Rising 420 metres above McLeod Bay at Whangārei Heads, Mount Manaia’s jagged volcanic pinnacles are sacred to Ngātiwai. The well-maintained track climbs steadily through nikau palms and kauri via timber steps to the dramatic summit lookout.","At the top, you look straight down onto Marsden Point refinery jetty, Bream Bay, and the Hen and Chicken Islands. Because it is a DOC kiwi sanctuary, dogs are not permitted."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Mt_Manaia.JPG/960px-Mt_Manaia.JPG","credit":"Follash, Public domain, Wikimedia Commons","file":"Mt_Manaia.JPG","wiki":"Mount Manaia"},{"id":"smugglers","name":"Smugglers Bay & Busby Head Loop","area":"Urquharts Bay, Whangārei Heads","cat":"both","catLabel":"Coastal & Bush","km":28,"driveMin":32,"walkTime":"1.5 hr loop (or 15 min to bay)","diff":"Easy","dog":"no","dogBadge":"🚫 No dogs (DOC reserve)","best":"Sunny day off · turquoise water & WWII gun emplacement","lat":-35.8453,"lon":174.5256,"paras":["Starting from the end of Urquharts Bay Road, a 10-minute walk over grassy farmland drops into Smugglers Bay—one of Northland’s prettiest white-sand coves, sheltered from ocean swells and framed by ancient pōhutukawa.","Continue around the coastal headland track to the WWII gun emplacements at Busby Head looking across the harbour entrance. Part of the Bream Head kiwi reserve, so no dogs allowed."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Mt_Lion.JPG/960px-Mt_Lion.JPG","credit":"Follash, Public domain, Wikimedia Commons","file":"Mt_Lion.JPG","wiki":"Bream Head"},{"id":"oceanbeach","name":"Ocean Beach (Whangārei Heads)","area":"Whangārei Heads","cat":"beach","catLabel":"Beaches","km":29,"driveMin":33,"walkTime":"45–90 min beach walk","diff":"Easy","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Low to mid tide · wild east-coast surf & giant dunes","lat":-35.8391,"lon":174.5597,"paras":["At the very end of the Whangārei Heads road, Ocean Beach opens out to 6 km of untamed Pacific surf, white sand dunes, and views of Bream Head’s bush-clad cliffs.","Check the council signs at the boardwalk entrance for current seasonal on-lead dog zones so kiwi habitat in the dunes is protected."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Mt_Aubrey_across_McLeod_Bay_%2880094597%29.jpg/960px-Mt_Aubrey_across_McLeod_Bay_%2880094597%29.jpg","credit":"Florian Bugiel, CC BY-SA 3.0, Wikimedia Commons","file":"Mt_Aubrey_across_McLeod_Bay_(80094597).jpg","wiki":"Whangārei Heads"},{"id":"ngunguru","name":"Ngunguru Estuary & Sandspit Walk","area":"Ngunguru, Tutukaka Coast","cat":"beach","catLabel":"Beaches","km":26,"driveMin":28,"walkTime":"45–60 min walk","diff":"Easy","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Mid to low tide · calm crystal-clear estuary edge","lat":-35.6319,"lon":174.5022,"paras":["A relaxed waterfront stroll along the pebbled and sandy edge of the Ngunguru Estuary, looking across the turquoise channel to the dazzling white dunes of the Ngunguru Sandspit.","Flat, easy going, and plenty of spots to grab a coffee or sit by the water with Zeus on-lead."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Ngunguru.jpg/960px-Ngunguru.jpg","credit":"Edouard Poor, CC BY-SA 2.0, Wikimedia Commons","file":"Ngunguru.jpg","wiki":"Ngunguru"},{"id":"kowharewa","name":"Kowharewa Bay & Church Bay","area":"Tutukaka Coast","cat":"beach","catLabel":"Beaches","km":30,"driveMin":32,"walkTime":"40 min coastal walk","diff":"Easy","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Calm sheltered bays · great picnic & afternoon stroll","lat":-35.6052,"lon":174.5244,"paras":["Just past Tutukaka Marina, Kowharewa Bay and neighbouring Church Bay are quiet, horseshoe-shaped pebble and sand coves sheltered from the wind.","A gentle coastal grass and beach walk links the bays with views out toward the Poor Knights Islands."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Xeronema_callistemon_on_Poor_Knights_Islands.JPG/960px-Xeronema_callistemon_on_Poor_Knights_Islands.JPG","credit":"Jasper33 at English Wikipedia, Public domain, Wikimedia Commons","file":"Xeronema_callistemon_on_Poor_Knights_Islands.JPG","wiki":"Poor Knights Islands"},{"id":"tutukaka","name":"Tutukaka Headland & Lighthouse Walk","area":"Tutukaka Coast","cat":"both","catLabel":"Coastal & Bush","km":31,"driveMin":34,"walkTime":"45 min return","diff":"Moderate","dog":"no","dogBadge":"🚫 No dogs (DOC reserve)","best":"Low to mid tide (causeway crosses at low/mid tide)","lat":-35.6111,"lon":174.5414,"paras":["Starts from picturesque Pacific Bay or Tutukaka Reserve, crosses a rocky tidal causeway onto Kukutauwhao Island (avoid high tide!), and climbs steps to the solar-powered Tutukaka South Gable Lighthouse.","Spectacular ocean views out to the Poor Knights Islands marine reserve."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Tutukaka_marina.jpg/960px-Tutukaka_marina.jpg","credit":"Wikimedia Commons","file":"3840px-Tutukaka_marina.jpg","wiki":"Tutukaka"},{"id":"matapouri","name":"Matapōuri Bay & Whale Bay Loop","area":"Tutukaka Coast","cat":"both","catLabel":"Coastal & Bush","km":37,"driveMin":38,"walkTime":"1–1.5 hr loop","diff":"Moderate","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Low to mid tide · white sand & pōhutukawa coves","lat":-35.5658,"lon":174.5097,"paras":["Matapōuri is famous for its sweeping white-sand horseshoe bay and estuary bridge. From the northern end of Matapōuri Beach, a bush track climbs over the ridge to secluded Whale Bay, where old pōhutukawa trees shade the sand.","Check seasonal summer dog rules on the main beaches before heading out."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/New_Zealand-_Matapouri_Bay.jpg/960px-New_Zealand-_Matapouri_Bay.jpg","credit":"Wikimedia Commons","file":"3840px-New_Zealand-_Matapouri_Bay.jpg","wiki":"Matapouri"},{"id":"waipu","name":"Waipū Cove to Langs Beach Trail","area":"Waipū / Bream Bay","cat":"both","catLabel":"Coastal & Bush","km":46,"driveMin":42,"walkTime":"1.5–2 hr return","diff":"Moderate","dog":"no","dogBadge":"🚫 No dogs (track section)","best":"Dry day · limestone stacks, native bush & ocean coves","lat":-36.0289,"lon":174.5067,"paras":["Starting at the southern end of Waipū Cove, this scenic coastal trail winds over rocky headlands, past pancake-like limestone stacks, and through regenerating coastal bush to Ding Bay and Langs Beach.","Look out across Bream Tail toward Sail Rock and the Hen and Chicken Islands."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/PohutukawaCornwallis.jpg/960px-PohutukawaCornwallis.jpg","credit":"Wikimedia Commons","file":"Metrosideros_excelsa.jpg","wiki":"Metrosideros excelsa"},{"id":"mangawhai","name":"Mangawhai Cliffs Walkway","area":"Mangawhai Heads","cat":"both","catLabel":"Coastal & Bush","km":72,"driveMin":60,"walkTime":"2–3 hr loop","diff":"Steep/Steps","dog":"no","dogBadge":"🚫 No dogs (DOC reserve)","best":"Must go within 2 hours of LOW TIDE for beach return","lat":-36.0825,"lon":174.5964,"paras":["One of Northland’s premier half-day walks: climb from Mangawhai Heads surf beach high along coastal cliffs among ancient pōhutukawa and nikau, with sweeping views from Bream Head to Great Barrier Island.","At the amphitheatre, drop down to the beach and walk back along the sand past giant rock arches (only passable around low tide; otherwise return via the clifftop track)."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Mangawhai_Tavern_2019_after_renovation_02.png/960px-Mangawhai_Tavern_2019_after_renovation_02.png","credit":"Zoohistorian, CC BY-SA 4.0, Wikimedia Commons","file":"Mangawhai_Tavern_2019_after_renovation_02.png","wiki":"Mangawhai"},{"id":"paihia","name":"Paihia to Ōpua Coastal Walkway","area":"Bay of Islands","cat":"both","catLabel":"Coastal & Bush","km":75,"driveMin":65,"walkTime":"2 hr one-way (or shorter loop)","diff":"Easy","dog":"lead","dogBadge":"🐕 Zeus friendly (on-lead)","best":"Great Bay of Islands day trip · boardwalks & bays","lat":-35.2917,"lon":174.0989,"paras":["Part of the Russell-to-Paihia coastal trail in the Bay of Islands, this easy track follows beaches, mangrove boardwalks, and coastal bush between Paihia and Ōpua Marina.","Great for a weekend road trip north with Zeus on-lead, followed by a gluten-free lunch overlooking the bay."],"img":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Paihia%2C_Williams_Road.jpg/960px-Paihia%2C_Williams_Road.jpg","credit":"Ulrich Lange, Bochum, Germany, CC BY 3.0, Wikimedia Commons","file":"Paihia,_Williams_Road.jpg","wiki":"Paihia"}];
const WK_KEY = 'walksBoard', WK_START = '2026-10-20';
const WK_LISTS = [['want', 'Want to do'], ['fav', 'Favourites ★'], ['done', 'Done recently']];
const WK_FILTS = [
  ['all', 'All (' + WALKS.length + ')'],
  ['zeus', '🐕 Zeus friendly'],
  ['offlead', '🐕 Off-lead'],
  ['beach', '🏖️ Beaches'],
  ['bush', '🌿 Bushwalks'],
  ['close', '🚗 Under 20 min drive'],
  ['easy', 'Easy walks']
];
const WK_SEED = {
  want: ['manaia', 'smugglers', 'abbey', 'mangawhai'],
  fav: ['onerahi', 'falls', 'ahreed', 'ruakaka'],
  done: ['parihaka', 'oceanbeach']
};
let wkFilt = 'all';
function wkGet() {
  let o = null; try { o = JSON.parse(localStorage.getItem(WK_KEY) || 'null'); } catch (e) { }
  if (!o || typeof o !== 'object') o = {};
  if (!o.lists || typeof o.lists !== 'object') o.lists = {};
  WK_LISTS.forEach(([k]) => { if (!Array.isArray(o.lists[k])) o.lists[k] = []; });
  if (!Array.isArray(o.custom)) o.custom = [];
  if (!o.seeded) {
    o.seeded = true;
    Object.entries(WK_SEED).forEach(([k, ids]) => {
      if (!o.lists[k].length) o.lists[k] = ids.map(id => { const w = WALKS.find(x => x.id === id); return w ? { id: 'wk-' + id, walkId: id, title: w.name, note: '' } : null; }).filter(Boolean);
    });
    wkSave(o);
  }
  return o;
}
function wkSave(o) { try { localStorage.setItem(WK_KEY, JSON.stringify(o)); } catch (e) { } }
function wkRestore(o) { if (o && o.lists && typeof o.lists === 'object') { o.seeded = true; wkSave(o); } }
function wkAllSpots() { const o = wkGet(); return WALKS.concat(o.custom || []); }
function wkById(id) { return wkAllSpots().find(w => w.id === id || w.name === id) || null; }
function walkToday(iso) {
  const d = Math.max(0, Math.round((parseD(iso || nzTodayISO()) - parseD(WK_START)) / DAY));
  return WALKS[((d % WALKS.length) + WALKS.length) % WALKS.length];
}
function wkMatchFilt(w, f) {
  if (!w) return true;
  f = f || wkFilt;
  if (f === 'all') return true;
  if (f === 'zeus') return w.dog === 'lead' || w.dog === 'offlead';
  if (f === 'offlead') return w.dog === 'offlead';
  if (f === 'beach') return w.cat === 'beach' || w.cat === 'both';
  if (f === 'bush') return w.cat === 'bush' || w.cat === 'both';
  if (f === 'close') return (w.driveMin || 99) <= 20;
  if (f === 'easy') return w.diff === 'Easy';
  return true;
}
function wkLabels(w) {
  if (!w) return [];
  const L = [];
  const dogCol = w.dog === 'offlead' ? '#15803d' : w.dog === 'lead' ? '#0d9488' : '#b91c1c';
  L.push([w.dogBadge || '🐕 Check dog rules', dogCol]);
  const catCol = w.cat === 'beach' ? '#0284c7' : w.cat === 'bush' ? '#16a34a' : '#7c3aed';
  L.push([w.catLabel || 'Walk', catCol]);
  const diffCol = w.diff === 'Easy' ? '#475569' : w.diff === 'Moderate' ? '#d97706' : '#dc2626';
  if (w.diff) L.push([w.diff, diffCol]);
  return L;
}
function wkCover(w, big) {
  if (!w) return '';
  return `<div class="tbcover trphoto${big ? ' big' : ''}${w.img ? '' : ' noimg'}" data-wiki="${esc(w.wiki || 'Whangārei')}">${w.img ? `<img src="${esc(w.img)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="travelImgFail(this)">` : ''}<div class="trnoimg">${I('pin')}<span>${esc(w.name)}</span></div></div>`;
}
function wkSpotCard(w, subOverride, big) {
  const drive = w.driveMin ? `🚗 ${w.driveMin} min (${w.km} km) from Onerahi` : (w.area || 'Northland');
  const walk = w.walkTime ? `🥾 ${w.walkTime}` : '';
  return `<button type="button" class="tbcard" onclick="wkOpenSpot(${jsArg(w.id)})">${wkCover(w, big)}<div class="tbbody">${tbLbl(wkLabels(w))}<div class="tbt">${esc(w.name)}</div><div class="tbs">${esc(subOverride || [drive, walk].filter(Boolean).join(' · '))}</div>${w.best ? `<div class="tbs" style="color:var(--brand,#0f766e);font-weight:600;opacity:1;margin-top:4px">☀️ ${esc(w.best)}</div>` : ''}<div class="tbicons">${I('pin')}<span>${esc(w.area || 'Northland')}</span><span class="tbdesc" aria-label="Has details">≡</span></div></div></button>`;
}
function wkUserCard(k, c) {
  const w = c.walkId ? wkById(c.walkId) : wkById(c.title);
  if (w && !wkMatchFilt(w)) return '';
  const drive = w && w.driveMin ? `🚗 ${w.driveMin} min (${w.km} km)` : '';
  const walk = w && w.walkTime ? `🥾 ${w.walkTime}` : '';
  return `<button type="button" class="tbcard" onclick="wkOpenCard('${k}',${jsArg(c.id)})">${w ? wkCover(w, false) : ''}<div class="tbbody">${tbLbl(w ? wkLabels(w) : [['Custom walk', '#0d9488']])}<div class="tbt">${esc(c.title)}</div><div class="tbs">${esc([drive, walk, w && w.area].filter(Boolean).join(' · '))}</div>${c.note ? `<div class="tbs" style="margin-top:4px">📝 ${esc(c.note.slice(0, 90))}</div>` : w && w.best ? `<div class="tbs" style="margin-top:3px">☀️ ${esc(w.best)}</div>` : ''}</div></button>`;
}
function wkBoardHtml() {
  const o = wkGet(), today = walkToday();
  const zeusPick = WALKS.filter(w => (w.dog === 'lead' || w.dog === 'offlead') && w.id !== today.id)[glDay() % 10] || WALKS[0];
  const sugCards = [
    wkSpotCard(today, `Spot of the day · 🚗 ${today.driveMin} min from Onerahi · 🥾 ${today.walkTime}`, true),
    wkSpotCard(zeusPick, `Zeus weekend pick · 🚗 ${zeusPick.driveMin} min · 🥾 ${zeusPick.walkTime}`, false)
  ].join('');
  const allFiltered = wkAllSpots().filter(w => wkMatchFilt(w));
  const dirHtml = allFiltered.map(w => wkSpotCard(w, null, false)).join('');
  const userCols = WK_LISTS.map(([k, title]) => {
    const cards = (o.lists[k] || []).map(c => wkUserCard(k, c)).filter(Boolean);
    return tbList(k, title, cards.length, cards.join(''), true, 'wk', 'No walks in this list yet');
  }).join('');
  return tbList('today', 'Spot of the day', 2, sugCards, false, 'wk') +
    userCols +
    tbList('dir', wkFilt === 'all' ? 'All Northland Spots' : 'Filtered Spots', allFiltered.length, dirHtml, true, 'wk', 'No spots match this filter');
}
function wkRedraw() {
  const el = document.getElementById('wklists'); if (!el) return render();
  const x = el.scrollLeft; el.innerHTML = wkBoardHtml(); el.scrollLeft = x;
  const ch = document.getElementById('wkchips'); if (ch) ch.innerHTML = wkChipsHtml();
}
function wkChipsHtml() {
  return WK_FILTS.map(([k, lbl]) => `<button type="button" class="chip${wkFilt === k ? ' on' : ''}" onclick="wkFilt='${k}';wkRedraw()">${esc(lbl)}</button>`).join('');
}
function wkDetailHtml(w) {
  const maps = w.lat && w.lon ? `https://www.google.com/maps/search/?api=1&query=${w.lat},${w.lon}` : `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(w.name + ' Northland NZ')}`;
  return `<div class="trcard tbsheet">
    ${w.img ? `<div class="trphoto" data-wiki="${esc(w.wiki || 'Whangārei')}"><img src="${esc(w.img)}" alt="${esc(w.name)}" referrerpolicy="no-referrer" onerror="travelImgFail(this)"><div class="trnoimg">${I('pin')}<span>${esc(w.name)}</span></div></div>
    ${w.credit ? `<div class="trcredit muted">Photo: ${esc(w.credit)}${w.file ? ` · <a href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(w.file)}" target="_blank" rel="noopener">source</a>` : ''}</div>` : ''}` : ''}
    ${tbLbl(wkLabels(w))}
    <h2 class="trname">${esc(w.name)}</h2>
    <div class="muted trcountry">${esc(w.area || 'Northland')} · ${esc(w.catLabel || 'Walk & Beach')}</div>
    <div class="trfacts" style="margin-top:10px">
      <div class="trfact"><span class="muted">From Onerahi</span><b>${w.driveMin ? w.driveMin + ' min drive' : 'Local'}</b><span class="muted">${w.km ? w.km + ' km from 16 Sherwood Rd' : 'Whangārei / Northland'}</span></div>
      <div class="trfact"><span class="muted">Walk time & grade</span><b>${esc(w.walkTime || '45–60 min')}</b><span class="muted">${esc(w.diff || 'Easy')} · ${esc(w.dogBadge || '')}</span></div>
    </div>
    ${w.best ? `<div class="callout green" style="margin:10px 0 6px">${I('sun')}<div><b>Best conditions:</b> ${esc(w.best)}</div></div>` : ''}
    <div class="trtext">${(w.paras || []).map(p => `<p>${esc(p)}</p>`).join('')}</div>
    <div class="btns" style="margin-top:10px">
      <a class="btn primary" href="${esc(maps)}" target="_blank" rel="noopener">${I('pin')} Directions in Maps</a>
      ${w.wiki ? `<a class="btn" href="https://en.wikipedia.org/wiki/${encodeURIComponent(w.wiki)}" target="_blank" rel="noopener">${I('ext')} Wikipedia</a>` : ''}
    </div>
  </div>`;
}
function wkOpenSpot(id) {
  const w = wkById(id); if (!w) return;
  const o = wkGet();
  const where = WK_LISTS.filter(([k]) => (o.lists[k] || []).some(c => c.walkId === w.id || c.title === w.name)).map(([, t]) => t);
  openSheet(esc(w.name), wkDetailHtml(w) + `<div class="tbmove"><div class="lbl">Save or move to your board…</div>${where.length ? `<div class="muted" style="font-size:.8125rem;margin-bottom:6px">Currently in: ${esc(where.join(', '))}</div>` : ''}<div class="chips">${WK_LISTS.map(([k, t]) => `<button type="button" class="chip" onclick="wkMoveSpot(${jsArg(w.id)},'${k}')">${esc(t)}</button>`).join('')}</div></div>`, null);
}
async function wkMoveSpot(id, k) {
  const w = wkById(id); if (!w) return;
  const o = wkGet(), t = (WK_LISTS.find(x => x[0] === k) || [])[1] || k;
  WK_LISTS.forEach(([j]) => { o.lists[j] = (o.lists[j] || []).filter(c => c.walkId !== w.id && c.title !== w.name); });
  o.lists[k].unshift({ id: uid('wk'), walkId: w.id, title: w.name, note: k === 'done' ? 'Walked ' + fmtW(nzTodayISO()) : '' });
  wkSave(o); await closeSheet(); wkRedraw(); toast(w.name + ' moved to ' + t + '.');
}
function wkFind(k, id) { const o = wkGet(), L = o.lists[k] || []; return { o, L, c: L.find(x => x.id === id) }; }
function wkOpenCard(k, id) {
  const { c } = wkFind(k, id); if (!c) return;
  const w = c.walkId ? wkById(c.walkId) : wkById(c.title);
  openSheet(esc(c.title), (w ? wkDetailHtml(w) : '') +
    `<label class="field"><span>Walk or beach name</span><input name="title" maxlength="120" value="${esc(c.title)}"></label>
    <label class="field"><span>Your notes (e.g. parking, tide, how Zeus liked it)</span><textarea name="note" rows="3" maxlength="1000">${esc(c.note || '')}</textarea></label>
    <label class="field"><span>Board column</span><select name="list">${WK_LISTS.map(([j, t]) => `<option value="${j}"${j === k ? ' selected' : ''}>${esc(t)}</option>`).join('')}</select></label>`,
    v => {
      if (!v.title) return 'Give the walk a name.';
      const f = wkFind(k, id); if (!f.c) return;
      f.c.title = v.title.slice(0, 120); f.c.note = (v.note || '').slice(0, 1000);
      const to = WK_LISTS.some(x => x[0] === v.list) ? v.list : k;
      if (to !== k) { f.o.lists[k] = f.L.filter(x => x.id !== id); f.o.lists[to].unshift(f.c); }
      wkSave(f.o); return () => wkRedraw();
    }, 'Save',
    `<button type="button" class="btn danger" onclick="wkDel('${k}',${jsArg(id)})">Remove</button>`);
}
async function wkDel(k, id) {
  const f = wkFind(k, id); if (!f.c) return;
  const before = JSON.stringify(f.o); f.o.lists[k] = f.L.filter(x => x.id !== id); wkSave(f.o);
  await closeSheet(); wkRedraw();
  toast('Removed from list.', 'Undo', () => { try { wkSave(JSON.parse(before)); } catch (e) { } wkRedraw(); });
}
function wkAdd(k) {
  const target = WK_LISTS.some(x => x[0] === k) ? k : 'want';
  const t = (WK_LISTS.find(x => x[0] === target) || [])[1] || 'Want to do';
  openSheet('Add a Northland walk or beach',
    `<label class="field"><span>Name</span><input id="wkt" name="title" maxlength="120" required placeholder="e.g. Marsden Point Beach or Glenbervie Forest"></label>
    <label class="field"><span>Area / Suburb</span><input name="area" maxlength="80" placeholder="e.g. Marsden Point / Whangārei"></label>
    <div style="display:flex;gap:10px">
      <label class="field" style="flex:1"><span>Type</span><select name="cat"><option value="both">Coastal &amp; Bush</option><option value="beach">Beach</option><option value="bush">Bushwalk</option></select></label>
      <label class="field" style="flex:1"><span>Dogs / Zeus</span><select name="dog"><option value="lead">🐕 Zeus on-lead</option><option value="offlead">🐕 Zeus off-lead</option><option value="no">🚫 No dogs</option></select></label>
    </div>
    <div style="display:flex;gap:10px">
      <label class="field" style="flex:1"><span>Drive mins from Onerahi</span><input name="driveMin" type="number" min="1" max="240" placeholder="20"></label>
      <label class="field" style="flex:1"><span>Walk time</span><input name="walkTime" maxlength="40" placeholder="45 min loop"></label>
    </div>
    <label class="field"><span>Best conditions / notes</span><textarea name="note" rows="2" maxlength="600" placeholder="e.g. Great at low tide, flat gravel path"></textarea></label>`,
    v => {
      if (!v.title) return 'Please enter a walk or beach name.';
      const o = wkGet(), id = uid('wkc');
      const dogBadge = v.dog === 'offlead' ? '🐕 Zeus off-lead areas' : v.dog === 'no' ? '🚫 No dogs (DOC reserve)' : '🐕 Zeus friendly (on-lead)';
      const catLabel = v.cat === 'beach' ? 'Beaches' : v.cat === 'bush' ? 'Bushwalk' : 'Coastal & Bush';
      const customSpot = { id, name: v.title.slice(0, 120), area: (v.area || 'Northland').slice(0, 80), cat: v.cat || 'both', catLabel, km: Math.round((+v.driveMin || 15) * 0.9), driveMin: +v.driveMin || 15, walkTime: (v.walkTime || '45 min').slice(0, 40), diff: 'Easy', dog: v.dog || 'lead', dogBadge, best: (v.note || '').slice(0, 140), img: '', paras: [v.note || 'Custom Northland walk added in My App.'] };
      o.custom = (o.custom || []).concat(customSpot);
      o.lists[target].unshift({ id: uid('wk'), walkId: id, title: customSpot.name, note: (v.note || '').slice(0, 600) });
      wkSave(o); return () => wkRedraw();
    }, 'Add to ' + t);
  setTimeout(() => { const i = document.getElementById('wkt'); if (i) i.focus(); }, 50);
}
function wkMenu(k) {
  const user = WK_LISTS.find(x => x[0] === k);
  const title = user ? user[1] : k === 'today' ? 'Spot of the day' : 'All Northland Spots';
  const txt = k === 'today' ? 'Rotates daily through 18 hand-picked Whangārei and Northland bushwalks and beaches, plus a Zeus-friendly pick.' : 'Tap any walk card for drive time from Onerahi, dog rules for Zeus, tide notes and Google Maps directions, or move it between your lists.';
  openSheet(esc(title), `<p class="muted" style="margin:0 0 10px">${esc(txt)}</p>`, null, 'Save', `<button type="button" class="btn primary" onclick="closeSheet().then(()=>wkAdd('${user ? user[0] : 'want'}'))">${I('plus')} Add a walk</button>`);
}
async function btAddWalks() {
  const s = snap(), b = btState();
  if (b.keys.includes('walks')) { if (!b.on) { b.on = true; await save(); render(); } toast('Walks is on your bottom tabs.'); return; }
  if (b.keys.length >= BT_MAX) { toast('Six tabs is the most. Remove one, then add Walks.'); btCustomise(); return; }
  const i = b.keys.indexOf('more'); b.keys.splice(i < 0 ? b.keys.length : i, 0, 'walks'); b.on = true; await save(); render(); toast('Walks added to your bottom tabs.', 'Undo', undoTo(s));
}
function walksMoreSub() {
  try { const w = walkToday(); return `Today: ${esc(w.name)} (${w.driveMin} min) · ${esc(w.dogBadge)}`; } catch (e) { return 'Whangārei & Northland bushwalks and beaches'; }
}
function WalksPage() {
  const today = walkToday(), btIn = (() => { try { const b = btState(); return b.on && b.keys.includes('walks'); } catch (e) { return true; } })();
  return `<button class="back" onclick="go('#more')">${I('left')} Explore &amp; More</button>
    <div class="chips scroll" id="wkchips" style="margin:0 0 10px">${wkChipsHtml()}</div>
    <div class="tbboard"><div class="tbbg" aria-hidden="true" style="background:linear-gradient(160deg,#064e3b,#0f766e 55%,#0f172a)">${today.img ? `<img src="${esc(today.img)}" alt="" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}</div>
    <div class="tbtop"><div><h1>Walks &amp; Beaches</h1><div style="font-size:.82rem;opacity:.9">Whangārei &amp; Northland · drive times from Onerahi &amp; Zeus badges</div></div><div style="display:flex;gap:6px"><button class="iconbtn" aria-label="Add walk" onclick="wkAdd('want')">${I('plus')}</button><button class="iconbtn" aria-label="Settings" onclick="go('#settings')">${I('gear')}</button></div></div>
    <div class="tblists" id="wklists">${wkBoardHtml()}</div></div>
    ${btIn ? '' : `<button type="button" class="btn small" style="margin:10px 0 0" onclick="btAddWalks()">${I('plus')} Add to bottom bar</button>`}
    <div class="foot">Swipe sideways between lists. Drive distances &amp; times are from 16 Sherwood Rd, Onerahi. Always check council/DOC signage for seasonal dog rules.</div>`;
}

/* ================= 2.28.18: TIDY & ORGANISE (#tidy) =================
   Calm, zero-pressure "One Small Spot at a Time" 10-minute micro-zone organiser.
   Includes "Pick a 10-Minute Spot for Me" randomiser, 3-step micro-checklists, room filters,
   and Trello columns: Suggested Spot, Next Up (10–15 min), In Progress, Sorted & Tidy ✅, Organising Tips & Systems. */
const TIDY_SPOTS = [{"id":"td-cords","title":"Spare charging cables & adapters drawer","zone":"tech","zoneLabel":"🔌 Tech & Cords","mins":10,"energy":"Easy couch job","steps":["Pull out one handful of tangled USB-C, Lightning, HDMI, and power cords.","Coil each working cable neatly and secure with a velcro tie or twist-tie.","Toss frayed cables and drop mystery power bricks into a \"check or recycle\" bag."]},{"id":"td-tv","title":"TV cabinet, soundbar & remotes reset","zone":"tech","zoneLabel":"🔌 Tech & Cords","mins":10,"energy":"Quick win","steps":["Wipe dust off the TV stand, soundbar, and streaming box.","Tuck any hanging HDMI or power leads neatly behind the cabinet.","Wipe down the remotes and group them in one spot."]},{"id":"td-desk","title":"Paperwork, receipts & manuals pile","zone":"tech","zoneLabel":"🔌 Tech & Cords","mins":12,"energy":"Low energy","steps":["Gather loose mail, power bills, and appliance receipts into one stack.","Snap a photo in My App Photos of any receipt or warranty worth keeping.","Recycle old envelopes, flyers, and paid paper statements."]},{"id":"td-gfpantry","title":"Gluten-free flours, pastas & sauces shelf","zone":"kitchen","zoneLabel":"🥫 Kitchen & GF Pantry","mins":10,"energy":"Quick win","steps":["Pull forward open packets of GF pasta, rice noodles, cornflour, and tamari.","Clip or seal open bags tightly and check best-before dates on sauces & stock.","Add any low gluten-free staples straight to the Shopping list."]},{"id":"td-fridge","title":"Fridge door & condiments shelf","zone":"kitchen","zoneLabel":"🥫 Kitchen & GF Pantry","mins":10,"energy":"Quick win","steps":["Take every bottle and jar off one fridge door shelf.","Wipe the shelf and sticky bottle bases with warm soapy water.","Toss expired jars and put safe GF sauces (BBQ, tamari, mayo) back together."]},{"id":"td-tubs","title":"Plastics & lunch containers drawer","zone":"kitchen","zoneLabel":"🥫 Kitchen & GF Pantry","mins":10,"energy":"Low energy","steps":["Take out the containers and match every tub with its lid.","Stack matching bases together and stand lids upright down the side.","Recycle any cracked tubs or orphan lids with no matching base."]},{"id":"td-spices","title":"Herbs, spices & taco seasonings rack","zone":"kitchen","zoneLabel":"🥫 Kitchen & GF Pantry","mins":10,"energy":"Low energy","steps":["Pull out all spice jars and seasoning packets.","Combine duplicate open jars (like paprika, cumin, or oregano) and check GF labels.","Put Friday/Saturday dinner favourites at the front within easy reach."]},{"id":"td-bits","title":"Screwdriver & drill-bit tray","zone":"garage","zoneLabel":"🔧 Garage & Tools","mins":10,"energy":"Quick win","steps":["Tip out loose drill bits, driver bits, and stray screws from the tool tray.","Put Phillips, square-drive, and hex bits back into their bit holder.","Drop loose screws and wall anchors into a clear jar for the next reno job."]},{"id":"td-paint","title":"Paint tins, rollers & reno brushes shelf","zone":"garage","zoneLabel":"🔧 Garage & Tools","mins":15,"energy":"Motivated 15 min","steps":["Tap lids firmly shut on leftover paint tins from Millesha’s, Mum’s, or home jobs.","Write the house & room name on top of each tin with a marker (e.g. \"Lounge walls\").","Throw out rock-hard brushes, dried-up gap filler tubes, and empty trays."]},{"id":"td-bench","title":"Workbench top 10-minute clear-off","zone":"garage","zoneLabel":"🔧 Garage & Tools","mins":10,"energy":"Quick win","steps":["Hang up or return any hand tools left out from the last job.","Brush sawdust, offcuts, and packaging into the rubbish bin.","Leave only the one current project or charger sitting on the bench."]},{"id":"td-spa","title":"Spa area, steps & towel hook reset","zone":"living","zoneLabel":"🛋️ Living & Spa","mins":10,"energy":"Quick win","steps":["Bring inside any used towels or glasses from around the spa.","Wipe down the spa cover edge and steps.","Hang a fresh dry towel ready for tonight’s 10pm soak."]},{"id":"td-couch","title":"Couch, throw blankets & coffee table","zone":"living","zoneLabel":"🛋️ Living & Spa","mins":10,"energy":"Quick win","steps":["Take any mugs, plates, or glasses back to the kitchen sink.","Fold the couch throw blanket and straighten the cushions.","Stack your current book and remotes neatly on the side table."]},{"id":"td-bedside","title":"Bedside table top & top drawer","zone":"bedroom","zoneLabel":"🛏️ Bedrooms & Storage","mins":10,"energy":"Low energy","steps":["Clear off old water glasses, receipts, and empty packets.","Keep only your night medication, watch charger, and current book on top.","Give the surface and lamp base a quick wipe."]},{"id":"td-linen","title":"Linen cupboard — one single shelf","zone":"bedroom","zoneLabel":"🛏️ Bedrooms & Storage","mins":10,"energy":"Low energy","steps":["Pick just one shelf of towels or sheets (leave the rest for another day).","Refold and tuck each sheet set inside one of its matching pillowcases.","Move any frayed old towels out to the garage rag pile."]},{"id":"td-entry","title":"Front door shoes, jackets & Zeus’s lead","zone":"bedroom","zoneLabel":"🛏️ Bedrooms & Storage","mins":10,"energy":"Quick win","steps":["Pair up work shoes, gym shoes, and dog-walking shoes neatly.","Put extra jackets or off-season shoes back in the wardrobe.","Hang Zeus’s lead and poo bags together on the hook."]},{"id":"td-fit-glove","title":"Honda Fit (MUL27) glovebox & centre console","zone":"cars","zoneLabel":"🚗 Cars","mins":10,"energy":"Quick win","steps":["Take a small rubbish bag out to the car and clear wrappers, old parking slips, and receipts.","Keep the service/WOF sheet, tyre gauge, and charging cable neat in the console.","Wipe the cupholders and dashboard with a damp cloth."]},{"id":"td-car-boot","title":"Car boot & reusable shopping bags","zone":"cars","zoneLabel":"🚗 Cars","mins":10,"energy":"Quick win","steps":["Take inside any tools, jackets, or items riding around in the boot.","Fold all New World and supermarket bags neatly inside one bag.","Quickly vacuum or shake out the boot mat."]}];
const TIDY_TIPS = [{"id":"tip-10min","title":"The 10-Minute Micro-Spot Rule","tag":"Mindset","body":"Never try to \"clean the garage\" or \"sort the kitchen\" after a 90-hour work week. Pick one single drawer, one shelf, or one tray, set a 10-minute timer, and stop when it rings. Small finished spots stay tidy."},{"id":"tip-onetouch","title":"The One-Touch Rule for Everyday Gear","tag":"Daily habit","body":"Instead of putting keys, work bag, gym gear, or mail down \"for now\" and moving them twice later, touch them once: straight onto their hook, into the laundry basket, or into the bin."},{"id":"tip-cords","title":"Velcro Ties & Zip-Bag Cord System","tag":"Tech & Cords","body":"Wrap spare cables with cheap velcro ties and group them into three clear zip-lock bags labelled \"USB-C\", \"HDMI & Audio\", and \"Power Leads\". You will never untangle a cord knot again."},{"id":"tip-gfzone","title":"Dedicated Top-Shelf Gluten-Free Zone","tag":"Kitchen & GF","body":"Keep gluten-free flours, breadcrumbs, pastas, and toaster bags on the upper shelf in clear containers. Crumbs only fall downwards, so top-shelf storage prevents cross-contamination and makes Friday/Saturday cooking faster."},{"id":"tip-jars","title":"Clear Jars for Screws, Wall Anchors & Bits","tag":"Garage & Reno","body":"Save 3–4 clear peanut-butter or pasta jars for the workbench: one for wood screws, one for GIB® anchors, one for nails/washers. Seeing what you have stops you buying a third packet at Bunnings."},{"id":"tip-pillowcase","title":"The Pillowcase Trick for Sheet Sets","tag":"Storage","body":"Fold the fitted sheet, flat sheet, and one pillowcase, then slide the whole bundle inside the second pillowcase. Every bed set stays together in one neat parcel."},{"id":"tip-photo","title":"Photo-Then-Recycle for Paperwork & Boxes","tag":"Paperwork","body":"Instead of keeping bulky appliance boxes, instruction booklets, and fading thermal receipts, snap the serial number and receipt into My App Photos with a tag, then recycle the paper."},{"id":"tip-carbag","title":"Fuel-Stop Door-Pocket Reset","tag":"Cars","body":"While the tank is filling up at the pump, spend 60 seconds emptying door pockets, cupholders, and receipts into the forecourt bin. Your car stays tidy with zero extra time."}];
const TD_KEY = 'tidyBoard';
const TD_LISTS = [['next', 'Next Up (10–15 min)'], ['doing', 'In Progress'], ['done', 'Sorted & Tidy ✅']];
const TD_ZONES = [
  ['all', 'All zones'],
  ['garage', '🔧 Garage & Tools'],
  ['tech', '🔌 Tech & Cords'],
  ['kitchen', '🥫 Kitchen & GF Pantry'],
  ['living', '🛋️ Living & Spa'],
  ['bedroom', '🛏️ Bedrooms & Storage'],
  ['cars', '🚗 Cars']
];
const TD_ZONE_COL = { garage: '#b45309', tech: '#2563eb', kitchen: '#ea580c', living: '#7c3aed', bedroom: '#0d9488', cars: '#16a34a' };
let tdZone = 'all';
function tdGet() {
  let o = null; try { o = JSON.parse(localStorage.getItem(TD_KEY) || 'null'); } catch (e) { }
  if (!o || typeof o !== 'object') o = {};
  if (!o.status || typeof o.status !== 'object') o.status = {};
  if (!o.steps || typeof o.steps !== 'object') o.steps = {};
  if (!o.notes || typeof o.notes !== 'object') o.notes = {};
  if (!o.doneAt || typeof o.doneAt !== 'object') o.doneAt = {};
  if (!Array.isArray(o.custom)) o.custom = [];
  if (!o.seeded) {
    o.seeded = true;
    o.status['td-cords'] = 'doing';
    o.status['td-spa'] = 'done'; o.doneAt['td-spa'] = nzTodayISO();
    o.status['td-fit-glove'] = 'done'; o.doneAt['td-fit-glove'] = addDays(nzTodayISO(), -2);
    o.pickId = 'td-gfpantry';
    tdSave(o);
  }
  return o;
}
function tdSave(o) { try { localStorage.setItem(TD_KEY, JSON.stringify(o)); } catch (e) { } }
function tdRestore(o) { if (o && typeof o === 'object') { o.seeded = true; tdSave(o); } }
function tdAllSpots() { const o = tdGet(); return TIDY_SPOTS.concat(o.custom || []); }
function tdById(id) { return tdAllSpots().find(s => s.id === id) || null; }
function tdStatusOf(id) { const st = tdGet().status[id]; return ['next', 'doing', 'done'].includes(st) ? st : 'next'; }
function tdPickedSpot() {
  const o = tdGet(), all = tdAllSpots().filter(s => tdZone === 'all' || s.zone === tdZone);
  const open = all.filter(s => tdStatusOf(s.id) !== 'done');
  const pool = open.length ? open : all;
  if (o.pickId) { const hit = pool.find(s => s.id === o.pickId); if (hit) return hit; }
  return pool[glDay() % Math.max(1, pool.length)] || TIDY_SPOTS[0];
}
function tdPickRandom(openModal) {
  const o = tdGet(), all = tdAllSpots().filter(s => (tdZone === 'all' || s.zone === tdZone) && tdStatusOf(s.id) !== 'done');
  const pool = all.length ? all : tdAllSpots();
  const others = pool.filter(s => s.id !== o.pickId);
  const pick = (others.length ? others : pool)[Math.floor(Math.random() * (others.length || pool.length))];
  if (pick) {
    o.pickId = pick.id; tdSave(o); tdRedraw();
    if (openModal) tdOpenSpot(pick.id);
    else toast('10-minute spot picked: ' + pick.title);
  }
}
function tdStepDone(id, idx) { const o = tdGet(); return !!((o.steps[id] || {})[idx]); }
function tdToggleStep(id, idx, checked) {
  const o = tdGet(); o.steps[id] = o.steps[id] || {}; o.steps[id][idx] = !!checked;
  const sp = tdById(id);
  if (sp && Array.isArray(sp.steps) && sp.steps.length) {
    const allDone = sp.steps.every((_, i) => o.steps[id][i]);
    const anyDone = sp.steps.some((_, i) => o.steps[id][i]);
    if (allDone) { o.status[id] = 'done'; o.doneAt[id] = nzTodayISO(); }
    else if (anyDone && tdStatusOf(id) === 'next') o.status[id] = 'doing';
  }
  tdSave(o); tdRedraw();
}
function tdSpotCard(s, hero) {
  const o = tdGet(), st = tdStatusOf(s.id), steps = s.steps || [];
  const doneN = steps.filter((_, i) => tdStepDone(s.id, i)).length;
  const col = TD_ZONE_COL[s.zone] || '#0d9488';
  const lbls = [[s.zoneLabel || 'Spot', col], [`⏱️ ${s.mins || 10} min`, '#475569']];
  if (hero) lbls.unshift(['✨ Suggested 10-Min Spot', '#0f766e']);
  else if (st === 'done') lbls.push(['✓ Sorted', '#16a34a']);
  else if (st === 'doing') lbls.push(['In Progress', '#d97706']);
  const stepPreview = steps.length ? `<div style="margin-top:6px;display:flex;flex-direction:column;gap:3px">${steps.map((stx, i) => `<div style="font-size:.77rem;display:flex;gap:5px;align-items:flex-start;opacity:${tdStepDone(s.id, i) ? '.55;text-decoration:line-through' : '.9'}"><span>${tdStepDone(s.id, i) ? '☑' : '☐'}</span><span>${esc(stx)}</span></div>`).join('')}</div>` : '';
  return `<button type="button" class="tbcard" onclick="tdOpenSpot(${jsArg(s.id)})"><div class="tbbody">${tbLbl(lbls)}<div class="tbt">${esc(s.title)}</div>${o.notes[s.id] ? `<div class="tbs">📝 ${esc(o.notes[s.id])}</div>` : ''}${stepPreview}<div class="tbicons"><span>${esc(s.energy || '10 min')}</span>${steps.length ? `<span>· ${doneN}/${steps.length} steps</span>` : ''}${o.doneAt[s.id] && st === 'done' ? `<span>· Done ${esc(fmtW(o.doneAt[s.id]))}</span>` : ''}</div></div></button>`;
}
function tdTipCard(tip) {
  return `<button type="button" class="tbcard" onclick="tdOpenTip(${jsArg(tip.id)})"><div class="tbbody">${tbLbl([['💡 ' + tip.tag, '#7c3aed']])}<div class="tbt">${esc(tip.title)}</div><div class="tbs">${esc(tip.body)}</div></div></button>`;
}
function tdBoardHtml() {
  const all = tdAllSpots().filter(s => tdZone === 'all' || s.zone === tdZone);
  const pick = tdPickedSpot();
  const sugHtml = pick ? tdSpotCard(pick, true) + `<button type="button" class="tbadd" onclick="tdPickRandom(false)">🎲 Swap for another 10-min spot</button>` : '';
  const listCols = TD_LISTS.map(([k, title]) => {
    const items = all.filter(s => tdStatusOf(s.id) === k);
    return tbList(k, title, items.length, items.map(s => tdSpotCard(s, false)).join(''), k !== 'done', 'td', k === 'done' ? 'Tick off a spot when sorted' : 'Nothing here');
  }).join('');
  const tipsHtml = TIDY_TIPS.map(tdTipCard).join('');
  return tbList('sug', 'Suggested Spot', pick ? 1 : 0, sugHtml, false, 'td') +
    listCols +
    tbList('tips', 'Organising Tips & Systems', TIDY_TIPS.length, tipsHtml, false, 'td');
}
function tdRedraw() {
  const el = document.getElementById('tdlists'); if (!el) return render();
  const x = el.scrollLeft; el.innerHTML = tdBoardHtml(); el.scrollLeft = x;
  const ch = document.getElementById('tdchips'); if (ch) ch.innerHTML = tdChipsHtml();
}
function tdChipsHtml() {
  return TD_ZONES.map(([k, lbl]) => `<button type="button" class="chip${tdZone === k ? ' on' : ''}" onclick="tdZone='${k}';tdRedraw()">${esc(lbl)}</button>`).join('');
}
function tdOpenSpot(id) {
  const s = tdById(id); if (!s) return;
  const o = tdGet(), st = tdStatusOf(s.id), steps = s.steps || [];
  const stepsHtml = steps.length ? `<div class="field"><span>3 quick steps (tap as you go — 10 mins max)</span><div class="flgsubs" id="tdstepbox">${steps.map((stx, i) => `<label class="flgsub"><input type="checkbox" ${tdStepDone(s.id, i) ? 'checked' : ''} onchange="tdToggleStep(${jsArg(s.id)},${i},this.checked)"><span${tdStepDone(s.id, i) ? ' class="done"' : ''}>${esc(stx)}</span></label>`).join('')}</div></div>` : '';
  openSheet(esc(s.title),
    `${tbLbl([[s.zoneLabel || 'Spot', TD_ZONE_COL[s.zone] || '#0d9488'], [`⏱️ ${s.mins || 10} min`, '#475569'], [s.energy || 'Zero pressure', '#0f766e']])}
    ${stepsHtml}
    <div class="tbmove" style="margin-top:10px"><div class="lbl">Move spot to…</div><div class="chips">${TD_LISTS.map(([k, t]) => `<button type="button" class="chip${st === k ? ' on' : ''}" onclick="tdSetStatus(${jsArg(s.id)},'${k}')">${esc(t)}</button>`).join('')}</div></div>
    <label class="field" style="margin-top:10px"><span>Notes (e.g. what’s left or what container you need)</span><textarea name="note" rows="2" maxlength="600">${esc(o.notes[s.id] || '')}</textarea></label>`,
    v => {
      const o2 = tdGet();
      if ((v.note || '').trim()) o2.notes[s.id] = v.note.trim().slice(0, 600); else delete o2.notes[s.id];
      tdSave(o2); return () => tdRedraw();
    }, 'Save note',
    `<button type="button" class="btn primary" onclick="tdSetStatus(${jsArg(s.id)},'done')">✓ Mark Sorted</button>`);
}
async function tdSetStatus(id, st) {
  const o = tdGet(), s = tdById(id); if (!s) return;
  o.status[id] = st;
  if (st === 'done') {
    o.doneAt[id] = nzTodayISO();
    if (Array.isArray(s.steps)) { o.steps[id] = {}; s.steps.forEach((_, i) => { o.steps[id][i] = true; }); }
    if (o.pickId === id) { const nxt = tdAllSpots().find(x => x.id !== id && tdStatusOf(x.id) !== 'done'); if (nxt) o.pickId = nxt.id; }
  } else if (st === 'next') {
    delete o.steps[id];
  }
  tdSave(o); await closeSheet(); tdRedraw();
  toast(st === 'done' ? 'Spot sorted! Nice 10-minute win.' : 'Moved to ' + (TD_LISTS.find(x => x[0] === st) || [0, st])[1] + '.');
}
function tdOpenTip(id) {
  const tip = TIDY_TIPS.find(x => x.id === id); if (!tip) return;
  openSheet(esc(tip.title), `${tbLbl([['💡 ' + tip.tag, '#7c3aed']])}<p style="font-size:1rem;line-height:1.5;margin:10px 0">${esc(tip.body)}</p>`, null);
}
function tdAdd(k) {
  const target = ['next', 'doing', 'done'].includes(k) ? k : 'next';
  openSheet('Add a 10-minute spot to sort',
    `<label class="field"><span>Spot name (keep it small!)</span><input id="tdt" name="title" maxlength="100" required placeholder="e.g. Top tool drawer or bedside shelf"></label>
    <div style="display:flex;gap:10px">
      <label class="field" style="flex:1"><span>Room / Zone</span><select name="zone">${TD_ZONES.filter(z => z[0] !== 'all').map(([z, l]) => `<option value="${z}">${esc(l)}</option>`).join('')}</select></label>
      <label class="field" style="flex:1"><span>Minutes</span><input name="mins" type="number" min="5" max="30" value="10"></label>
    </div>
    <label class="field"><span>Step 1</span><input name="s1" maxlength="120" placeholder="e.g. Take everything out of the drawer"></label>
    <label class="field"><span>Step 2</span><input name="s2" maxlength="120" placeholder="e.g. Toss broken bits & group the rest"></label>
    <label class="field"><span>Step 3</span><input name="s3" maxlength="120" placeholder="e.g. Put everyday items back in front"></label>`,
    v => {
      if (!v.title) return 'Give the spot a name.';
      const o = tdGet(), id = uid('tdc'), z = TD_ZONES.find(x => x[0] === v.zone) || TD_ZONES[1];
      const steps = [v.s1, v.s2, v.s3].map(x => String(x || '').trim()).filter(Boolean);
      if (!steps.length) steps.push('Clear out clutter and rubbish', 'Group like with like', 'Put back only what belongs here');
      o.custom = (o.custom || []).concat({ id, title: v.title.slice(0, 100), zone: z[0], zoneLabel: z[1], mins: +v.mins || 10, energy: 'Custom spot', steps });
      o.status[id] = target; tdSave(o); return () => tdRedraw();
    }, 'Add spot');
  setTimeout(() => { const i = document.getElementById('tdt'); if (i) i.focus(); }, 50);
}
function tdMenu(k) {
  const list = TD_LISTS.find(x => x[0] === k);
  const title = list ? list[1] : k === 'sug' ? 'Suggested 10-Minute Spot' : 'Organising Tips & Systems';
  openSheet(esc(title), `<p class="muted" style="margin:0 0 10px">One small drawer, shelf, or corner at a time. No pressure and no overdue dates—just pick a 10-minute win when you feel like it.</p>`, null, 'Save',
    `<button type="button" class="btn primary" onclick="closeSheet().then(()=>tdPickRandom(true))">🎲 Pick a 10-min spot</button> <button type="button" class="btn" onclick="closeSheet().then(()=>tdAdd('${list ? list[0] : 'next'}'))">${I('plus')} Add spot</button>`);
}
async function btAddTidy() {
  const s = snap(), b = btState();
  if (b.keys.includes('tidy')) { if (!b.on) { b.on = true; await save(); render(); } toast('Tidy is on your bottom tabs.'); return; }
  if (b.keys.length >= BT_MAX) { toast('Six tabs is the most. Remove one, then add Tidy.'); btCustomise(); return; }
  const i = b.keys.indexOf('more'); b.keys.splice(i < 0 ? b.keys.length : i, 0, 'tidy'); b.on = true; await save(); render(); toast('Tidy added to your bottom tabs.', 'Undo', undoTo(s));
}
function tidyMoreSub() {
  try {
    const all = tdAllSpots(), done = all.filter(s => tdStatusOf(s.id) === 'done').length, p = tdPickedSpot();
    return `${done} of ${all.length} spots sorted · Next 10-min pick: ${esc(p.title)}`;
  } catch (e) { return 'One small 10-minute spot at a time'; }
}
function TidyPage() {
  const all = tdAllSpots(), done = all.filter(s => tdStatusOf(s.id) === 'done').length;
  const btIn = (() => { try { const b = btState(); return b.on && b.keys.includes('tidy'); } catch (e) { return true; } })();
  return `<button class="back" onclick="go('#projects')">${I('left')} Projects</button>
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px;flex-wrap:wrap">
      <button type="button" class="btn primary small" onclick="tdPickRandom(true)">🎲 Pick a 10-Minute Spot for Me</button>
      <button type="button" class="btn small" onclick="tdAdd('next')">${I('plus')} Add spot</button>
    </div>
    ${progLine(done, all.length, 'Micro-spots sorted & tidy', 'pgsm')}
    <div class="chips scroll" id="tdchips" style="margin:8px 0 10px">${tdChipsHtml()}</div>
    <div class="tbboard"><div class="tbbg" aria-hidden="true" style="background:linear-gradient(160deg,#115e59,#0d9488 50%,#1e293b)"></div>
    <div class="tbtop"><div><h1>Tidy &amp; Organise</h1><div style="font-size:.82rem;opacity:.9">One small 10-minute spot at a time · zero pressure</div></div><button class="iconbtn" aria-label="Settings" onclick="go('#settings')">${I('gear')}</button></div>
    <div class="tblists" id="tdlists">${tdBoardHtml()}</div></div>
    ${btIn ? '' : `<button type="button" class="btn small" style="margin:10px 0 0" onclick="btAddTidy()">${I('plus')} Add to bottom bar</button>`}
    <div class="foot">Swipe sideways between lists. Pick one small shelf, drawer or tray for 10 minutes—no big blitzes required.</div>`;
}


